var data = msg.payload;
if (typeof data === 'string') {
    try {
        data = JSON.parse(data);
    } catch (e) {
        node.warn("Error parsing JSON");
        return null;
    }
}

var value = parseFloat(data.value);
if (isNaN(value)) {
    node.warn("Discarding reading without a numeric value: " + msg.topic);
    return null;
}

var topicParts = msg.topic.split('/');
var location = topicParts.length > 2 ? topicParts[2] : "unknown";
var sensorType = topicParts.length > 3 ? topicParts[3] : "unknown";

// Point time = sensor timestamp (epoch seconds); ISO strings still accepted, fallback to arrival time
var time = new Date();
if (typeof data.timestamp === 'number') {
    time = new Date(data.timestamp * 1000);
} else if (data.timestamp) {
    var parsed = new Date(data.timestamp);
    if (!isNaN(parsed.getTime())) {
        time = parsed;
    }
}

msg.measurement = "sensors";
msg.payload = [
    {
        value: value,
        lat: parseFloat(data.lat) || 0,
        lon: parseFloat(data.lon) || 0,
        time: time  // the influxdb node uses the "time" field as the point timestamp
    },
    {
        sensorid: String(data.sensorid || "unknown"),
        location: String(location),
        type: String(sensorType),
        unit: String(data.unit || "")
    }
];
return msg;

var chatId = env.get("TELEGRAM_CHAT_ID");

// The telegram node only accepts text: JSON alerts (composite rules, config acks) arrive parsed as objects
var content = msg.payload;
if (typeof content !== 'string') {
    content = JSON.stringify(content);
}

msg.payload = {
    chatId: chatId,
    type: 'message',
    content: content
};

return msg;

