}

var runtimeConfig = flow.get('runtime_config') || { thresholds: {}, rules: {}, planner: {} };

if (msg.topic === 'City/update/thresholds' && data && data.thresholds) {
    runtimeConfig.thresholds = data.thresholds;
}

if (msg.topic === 'City/update/policies' && data) {
    runtimeConfig.planner = data.planner || runtimeConfig.planner || {};
}

if (msg.topic && msg.topic.indexOf('City/update/rules/') === 0 && data) {
    var parts = msg.topic.split('/');
    var ruleName = parts.length >= 4 ? parts[3] : 'unknown';
    runtimeConfig.rules = runtimeConfig.rules || {};
    runtimeConfig.rules[ruleName] = data;
}

flow.set('runtime_config', runtimeConfig);
return null;

