}

var emType = data.type || 'unknown';
var location = data.location || 'unknown';
var severity = data.severity || 'none';
var active = data.active ? 1 : 0;

msg.measurement = 'emergencies';
msg.payload = [
    {
        active: active,
        severity_level: severity === 'catastrophic' ? 3 : (severity === 'critical' ? 2 : (severity === 'warning' ? 1 : 0))
    },
    {
        emergency_type: String(emType),
        location: String(location),
        severity: String(severity)
    }
];
return msg;

var data = msg.payload;
if (typeof data === 'string') {
    try { data = JSON.parse(data); } catch (e) { return null; }
}

// Only handle threshold updates
if (msg.topic !== "City/update/thresholds") return null;

var thresholds = data.thresholds;
if (!thresholds) return null;

var messages = [];
var types = Object.keys(thresholds);
for (var i = 0; i < types.length; i++) {
    var t = types[i];
    messages.push({
        measurement: "thresholds",
        payload: [
            { value: parseFloat(thresholds[t]) },
            { type: String(t) }
        ]
    });
}
return [messages];

var runtime = flow.get('runtime_config') || { thresholds: {}, rules: {}, planner: {} };
var thresholds = runtime.thresholds || {};
var rules = runtime.rules || {};
var planner = runtime.planner || {};

function h(val) {
    return String(val === undefined || val === null ? '' : val)
        .replace(/&/g, '&amp;')
        .replace(/</g, '&lt;')
        .replace(/>/g, '&gt;')
        .replace(/"/g, '&quot;')
        .replace(/'/g, '&#39;');
}

function num(obj, key, fallback) {
    var v = obj && obj[key];
    return (v === undefined || v === null || v === '') ? fallback : v;
}

