msg.headers = { 'Content-Type': 'text/html; charset=utf-8' };
msg.payload = html;
return msg;

var body = msg.payload || {};
var current = flow.get('runtime_config') || { thresholds: {}, rules: {}, planner: {} };
var mqttMessages = [];

function push(topic, payload) {
    mqttMessages.push({ topic: topic, payload: payload, retain: true, qos: 1 });
}

if (body.thresholds) {
    current.thresholds = body.thresholds;
    push('City/update/thresholds', { thresholds: body.thresholds });
}

if (body.planner) {
    current.planner = body.planner;
    push('City/update/policies', { planner: body.planner });
}

if (body.rules) {
    current.rules = current.rules || {};
    Object.keys(body.rules).forEach(function(ruleName) {
        current.rules[ruleName] = body.rules[ruleName];
        push('City/update/rules/' + ruleName, body.rules[ruleName]);
    });
}

flow.set('runtime_config', current);

var response = {
    message: 'Policies published to MQTT and saved in Node-RED runtime context.',
    current: current
};

return [mqttMessages, { payload: response, headers: { 'Content-Type': 'application/json' } }];

var defaults = {
    "temperature": 30.0,
    "humidity": 80.0,
    "co2": 1000.0,
    "traffic_speed": 80.0,
    "noise_level": 85.0,
    "seismic": 4.0,
    "rain_level": 50.0
};

var messages = [];
var types = Object.keys(defaults);
for (var i = 0; i < types.length; i++) {
    var t = types[i];
    messages.push({
        measurement: "thresholds",
        payload: [
            { value: defaults[t] },
            { type: String(t) }
        ]
    });
}
return [messages];

var chatId = env.get("TELEGRAM_CHAT_ID");
var data = msg.payload;
var messageText = "";

if (data.active === true) {
    // 🔴 Messaggio di EMERGENZA (Pallino Rosso)
    messageText = "🔴 **EMERGENCY ALERT**\n\n" +
                  "Type: " + data.type.toUpperCase() + "\n" +
                  "Location: " + data.location + "\n" +
                  "Severity: " + data.severity.toUpperCase() + "\n" +
                  "Timestamp: " + data.timestamp + "\n" +
                  "Status: ACTIVE";
} else {
    // 🟢 Messaggio di RECOVERY (Pallino Verde)
    var locationName = data.location && data.location !== "" ? data.location : "General Area";

    messageText = "🟢 **RECOVERY STATUS**\n\n" +
                  "The situation has been resolved.\n\n" +
                  "Type: " + data.type.toUpperCase() + "\n" +
                  "Location: " + locationName + "\n" +
                  "Timestamp: " + data.timestamp + "\n" +
                  "Status: RECOVERED";
}

msg.payload = {
    chatId: chatId,
    type: 'message',
    content: messageText
};

return msg;
